export const ONLINE_QUIZ_DATABASE = GRADES_QUIZ_DATA;
export type GradeQuizData = GradeQuizInfo;
export type QuizTest = UnitQuizTest;
export type QuizUnit = UnitQuizInfo;

export function getQuizUnitsByGrade(grade: number): UnitQuizInfo[] {
  const g = GRADES_QUIZ_DATA.find(item => item.grade === grade);
  return g ? g.units : [];
}

export function getQuizTest(grade: number, unitNumber: number, testNumber: number): UnitQuizTest | undefined {
  const units = getQuizUnitsByGrade(grade);
  const u = units.find(item => item.unitNumber === unitNumber);
  if (!u) return undefined;
  return u.tests.find(t => t.testNumber === testNumber);
}

export interface QuizAttemptResult {
  grade: number;
  unitNumber: number;
  testNumber: number;
  score: number;
  totalQuestions: number;
  correctCount: number;
  completedAt: string;
  timeSpentSeconds: number;
  selectedAnswers?: Record<number, number>;
}

export function saveQuizAttempt(result: QuizAttemptResult): void {
  try {
    const key = `quiz_attempt_g${result.grade}_u${result.unitNumber}_t${result.testNumber}`;
    localStorage.setItem(key, JSON.stringify(result));
    const allKey = 'quiz_attempts_history';
    const raw = localStorage.getItem(allKey);
    const history: QuizAttemptResult[] = raw ? JSON.parse(raw) : [];
    history.unshift(result);
    localStorage.setItem(allKey, JSON.stringify(history.slice(0, 50)));
  } catch (err) {
    console.warn('Cannot save quiz attempt:', err);
  }
}

export function getQuizAttempt(grade: number, unitNumber: number, testNumber: number): QuizAttemptResult | null {
  try {
    const key = `quiz_attempt_g${resultKey(grade, unitNumber, testNumber)}`;
    const raw = localStorage.getItem(key);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

function resultKey(grade: number, unitNumber: number, testNumber: number): string {
  return `${grade}_u${unitNumber}_t${testNumber}`;
}
